-- U4 Import: tables, constraints, indexes and row-level policies (BR41.1, BR41.7, BR41.10, NFR1.44, NFR1.52,
-- NFR3.13). Conventions are those of 20261024_directory_schema.sql and 20261036_notifications_schema.sql:
-- schema-neutral (the migration runner sets the session search path, every function pins its own with
-- `set search_path from current`), uuid keys generated by the database, `organization_id` on every table
-- that belongs to an organization, an integer `version` on the run and the conflict (people change them at
-- the same time), timestamps in UTC. Inside Import the tables are linked by composite foreign keys, so a child
-- row can never belong to another organization or run than its parent. The ids of other blocks (the family
-- or task a staged row was matched to) are typed ids with no foreign key (ADR-001).
--
-- Who reads what. The import is the super admin's, and a run belongs to the super admin who started it: only
-- that account reads its run, its rows and its conflicts. The staged rows hold the parsed workbook (names,
-- contact details, notes), which is personal data, so they are a table of their own that only the starting
-- super admin can read or delete (and the system expiry function, which runs as the owner); no other super
-- admin, group admin, teacher, parent, the service-role key or a signed-out request sees one. The long-term
-- history (runs, rows, conflicts) holds file names, sheet names, row numbers, counts and fixed reason texts,
-- and no person's name, e-mail address or phone number. Every change goes through the named functions of the
-- next files; the service-role key gets no table right.
--
-- Additions to entities.md, kept on purpose and recorded in code-summary.md: `import_rows.warning_count`
-- (the count of dropped phone values and profile texts of the row, BR41.2), `import_runs.changed_summary`
-- (the "<group> csoport: n módosítás" lines of the preview, group names and counts only), and on the staged
-- rows the classification the preview made (`unit_ref`, `is_leader`, `match_class`, `conflict_message`,
-- `row_conflict`), which the commit compares with its own second matching (BR41.6). The staged rows are
-- deleted when the run ends, and so are these columns.

-- ---------------------------------------------------------------------------------------------------
-- The fixed registry of the 17 workbook sheets (BR41.10), seeded below and not edited by screens. It holds
-- no organization: the workbook structure is defined by the application.
-- ---------------------------------------------------------------------------------------------------
create table sheet_registry (
  sheet text primary key check (char_length(sheet) between 1 and 100),
  mode text not null check (mode in ('interactive', 'read_only_archive')),
  destination text not null check (char_length(destination) between 1 and 300),
  owner_label text not null check (char_length(owner_label) between 1 and 100),
  sort_order integer not null unique check (sort_order between 1 and 17)
);

-- One upload of a workbook through preview, resolution, commit and recovery (BR41.3 to BR41.9).
create table import_runs (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references organizations (id),
  -- The file name only, shown as the 'Forrás' line: no path separator.
  workbook_name text not null check (char_length(workbook_name) between 1 and 200 and workbook_name !~ '[/\\]'),
  -- SHA-256 of the staged rows in a fixed order; a commit must present it (BR41.6).
  workbook_fingerprint text not null check (workbook_fingerprint ~ '^[a-f0-9]{64}$'),
  status text not null default 'previewed'
    check (status in ('previewed', 'confirmed', 'committed', 'interrupted', 'recovered', 'cancelled', 'expired')),
  -- The progress step the import screen shows after the upload (steps 1 to 3 are the screen's own).
  step integer not null default 4 check (step in (4, 5, 6, 7)),
  total_rows integer not null check (total_rows >= 0),
  imported_rows integer not null default 0 check (imported_rows >= 0),
  skipped_rows integer not null default 0 check (skipped_rows >= 0),
  -- The group names and counts of the preview, for example 'Boróka csoport: 2 módosítás'.
  changed_summary jsonb not null default '[]'::jsonb check (jsonb_typeof(changed_summary) = 'array'),
  -- Opaque actor id: only this super admin reads the run's staged rows (BR41.7).
  started_by_account_id uuid not null,
  committed_at timestamptz,
  expires_at timestamptz not null,
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (imported_rows + skipped_rows <= total_rows),
  check ((status in ('committed', 'recovered')) = (committed_at is not null)),
  check (expires_at > created_at),
  unique (id, organization_id)
);
-- One open run per super admin and organization (BR41.3): a second preview cancels the first, and the
-- database makes a race between two previews impossible to win twice.
create unique index import_runs_one_open on import_runs (organization_id, started_by_account_id)
  where status in ('previewed', 'confirmed', 'interrupted');
-- The status lookup (the admin's latest run) and the expiry sweep.
create index import_runs_by_starter on import_runs (organization_id, started_by_account_id, created_at desc);
create index import_runs_expiry on import_runs (status, expires_at);

-- The history of one workbook row: where it came from and what happened to it. No personal data (BR41.8).
create table import_rows (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  import_run_id uuid not null,
  sheet text not null references sheet_registry (sheet),
  row_number integer not null check (row_number >= 1),
  -- Sheet and row number: the stable identity of the row.
  source_key text not null check (char_length(source_key) between 1 and 256),
  outcome text not null default 'staged'
    check (outcome in ('staged', 'created', 'updated', 'skipped', 'archived', 'conflict', 'failed')),
  warning_count integer not null default 0 check (warning_count >= 0),
  foreign key (import_run_id, organization_id) references import_runs (id, organization_id),
  unique (import_run_id, source_key),
  unique (id, import_run_id)
);
create index import_rows_outcome on import_rows (import_run_id, outcome);

-- The parsed workbook row waiting for the commit: names, contact details and notes, so personal data
-- (BR41.7). Deleted when the run is committed, recovered, cancelled or expired (BR41.8). The payload is an
-- object of string values, each at most 10000 characters; the optional profile is present only when the
-- consent column said 'igen'.
create or replace function import_payload_valid(p_payload jsonb) returns boolean
language sql immutable set search_path from current
as $$
  select jsonb_typeof(p_payload) = 'object'
     and (select count(*) from jsonb_object_keys(p_payload)) <= 20
     and not exists (
       select 1 from jsonb_each(p_payload) e
        where jsonb_typeof(e.value) <> 'string' or char_length(e.value #>> '{}') > 10000)
$$;

create table import_staged_rows (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  import_run_id uuid not null,
  source_key text not null check (char_length(source_key) between 1 and 256),
  payload jsonb not null check (import_payload_valid(payload)),
  -- What the preview made of the row (the unit it belongs to, whether it leads the unit, and the decision).
  -- A hash, not the key: a long cell must not reach an index.
  unit_ref text not null check (unit_ref ~ '^[a-f0-9]{64}$'),
  is_leader boolean not null default false,
  match_class text not null default 'none' check (match_class in ('create', 'update', 'none', 'conflict')),
  conflict_message text check (conflict_message is null or conflict_message in (
    'Több egyező család.', 'Az elem már létezik.', 'Ismétlődő sor a fájlban.', 'Ismeretlen csoport.',
    'Ismeretlen család.', 'Hibás adat a sorban.', 'Több egyező feladat.', 'Az elem megváltozott.')),
  -- True when the conflict is this row's alone (a family of a task row); false when it belongs to the whole unit.
  row_conflict boolean not null default false,
  -- What the row was matched to at preview time, and the record's version, which the commit re-checks.
  matched_record_type text check (matched_record_type in ('family', 'task')),
  matched_record_id uuid,
  matched_record_version integer check (matched_record_version is null or matched_record_version >= 1),
  check ((match_class = 'conflict') = (conflict_message is not null)),
  check ((matched_record_type is null) = (matched_record_id is null)
         and (matched_record_type is null) = (matched_record_version is null)),
  foreign key (import_run_id, organization_id) references import_runs (id, organization_id),
  foreign key (import_run_id, source_key) references import_rows (import_run_id, source_key),
  unique (import_run_id, source_key)
);
create index import_staged_rows_unit on import_staged_rows (import_run_id, unit_ref);

-- A row (or a unit of rows, represented by its first row) that does not match cleanly and needs the admin's
-- decision. Sheet and row number only: never a name (BR41.4, answer Q4). The message is from a closed list.
create table import_conflicts (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  import_run_id uuid not null,
  import_row_id uuid not null,
  row_label text not null check (char_length(row_label) between 1 and 200),
  message text not null check (message in (
    'Több egyező család.', 'Az elem már létezik.', 'Ismétlődő sor a fájlban.', 'Ismeretlen csoport.',
    'Ismeretlen család.', 'Hibás adat a sorban.', 'Több egyező feladat.', 'Az elem megváltozott.')),
  resolution text check (resolution is null or resolution in ('keep_existing', 'use_import')),
  version integer not null default 1 check (version >= 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (import_run_id, organization_id) references import_runs (id, organization_id),
  foreign key (import_row_id, import_run_id) references import_rows (id, import_run_id),
  unique (import_row_id)
);
create index import_conflicts_run on import_conflicts (import_run_id, resolution);
create trigger import_conflicts_touch_version before update on import_conflicts
  for each row execute function platform_touch_version();

