-- ---------------------------------------------------------------------------------------------------
-- The reader of the policies: a super admin of the run's organization, in an active session, who is the
-- account that started the run. Asked once per statement where the policy calls it with a constant, and
-- through the run's own row otherwise. Executable by signed-in accounts because the policies call it.
-- ---------------------------------------------------------------------------------------------------
create or replace function import_run_reached(p_run_id uuid, p_organization_id uuid) returns boolean
language sql stable security definer set search_path from current
as $$
  select has_super_scope(p_organization_id)
     and exists (select 1 from import_runs r
                  where r.id = p_run_id and r.organization_id = p_organization_id
                    and r.started_by_account_id = auth.uid())
$$;

-- ---------------------------------------------------------------------------------------------------
-- Row-level security.
-- ---------------------------------------------------------------------------------------------------
alter table sheet_registry enable row level security;
alter table import_runs enable row level security;
alter table import_rows enable row level security;
alter table import_staged_rows enable row level security;
alter table import_conflicts enable row level security;

-- The registry is not personal; any super admin of any organization reads it.
create policy sheet_registry_read on sheet_registry for select to authenticated
  using (current_session_is_active() and exists (
    select 1 from app_role_grants g
     where g.subject_id = auth.uid() and g.role = 'super_admin' and g.revoked_at is null));
create policy import_runs_read on import_runs for select to authenticated
  using (started_by_account_id = (select auth.uid()) and has_super_scope(organization_id));
create policy import_rows_read on import_rows for select to authenticated
  using (import_run_reached(import_run_id, organization_id));
create policy import_conflicts_read on import_conflicts for select to authenticated
  using (import_run_reached(import_run_id, organization_id));
-- The staged payload: the starting super admin reads and deletes it, nobody else (BR41.7).
create policy import_staged_rows_read on import_staged_rows for select to authenticated
  using (import_run_reached(import_run_id, organization_id));
create policy import_staged_rows_delete on import_staged_rows for delete to authenticated
  using (import_run_reached(import_run_id, organization_id));

revoke all on sheet_registry, import_runs, import_rows, import_staged_rows, import_conflicts
  from public, anon, authenticated, service_role;
grant select on sheet_registry, import_runs, import_rows, import_conflicts to authenticated;
grant select, delete on import_staged_rows to authenticated;

revoke all on function import_payload_valid(jsonb), import_run_reached(uuid, uuid)
  from public, anon, authenticated, service_role;
grant execute on function import_run_reached(uuid, uuid) to authenticated;
